package com.easytempoross;

/**
 * When the louder stop chime plays. Deposit countdown ticks (3, 2, 1) always stay on crate loads.
 */
public enum ChimeMode
{
	ALL_ACTIONS("All Actions"),
	DEPOSIT_ONLY("Deposit Only");

	private final String label;

	ChimeMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.easytempoross;

/**
 * Client-free rules for the optional stop chime when an AFK step finishes,
 * and for the double-spot cue when that click is actually needed.
 */
final class ChimePolicy
{
	private ChimePolicy()
	{
	}

	static boolean shouldPlayActionStop(RotationStep previous, RotationStep current, ChimeMode mode)
	{
		if (mode != ChimeMode.ALL_ACTIONS || previous == null || current == null || previous == current)
		{
			return false;
		}
		return isAfkStep(previous) && !isDeposit(previous) && !sameActivity(previous, current);
	}

	/**
	 * Edge-trigger: play once when the helper newly wants {@link RotationStep#FISH_DOUBLE}
	 * and inventory still has room. Holding the same state must not re-chime.
	 */
	static boolean shouldPlayDoubleFish(boolean enabled, boolean inMinigame, RotationStep step,
		int emptySlots, boolean wasWanted)
	{
		boolean want = wantsDoubleFish(enabled, inMinigame, step, emptySlots);
		return want && !wasWanted;
	}

	static boolean wantsDoubleFish(boolean enabled, boolean inMinigame, RotationStep step, int emptySlots)
	{
		return enabled && inMinigame && step == RotationStep.FISH_DOUBLE && emptySlots > 0;
	}

	static boolean isDeposit(RotationStep step)
	{
		return step == RotationStep.DEPOSIT || step == RotationStep.DEPOSIT_KEEP3;
	}

	static boolean isAfkStep(RotationStep step)
	{
		switch (step)
		{
			case FISH:
			case FISH_DOUBLE:
			case COOK:
			case FILL_PUMP:
			case SPIRIT:
			case DEPOSIT:
			case DEPOSIT_KEEP3:
				return true;
			default:
				return false;
		}
	}

	static boolean sameActivity(RotationStep previous, RotationStep current)
	{
		return (isFish(previous) && isFish(current))
			|| (isDeposit(previous) && isDeposit(current));
	}

	private static boolean isFish(RotationStep step)
	{
		return step == RotationStep.FISH || step == RotationStep.FISH_DOUBLE;
	}
}

package com.easytempoross;

/**
 * Which clickboxes to outline: the current action, the following destination, both, or neither.
 */
public enum ClickHighlight
{
	THIS("This click"),
	THIS_AND_NEXT("This click & next"),
	NEXT("Next only"),
	OFF("Off");

	private final String label;

	ClickHighlight(String label)
	{
		this.label = label;
	}

	public boolean showsThis()
	{
		return this == THIS || this == THIS_AND_NEXT;
	}

	public boolean showsNext()
	{
		return this == THIS_AND_NEXT || this == NEXT;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.easytempoross;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Folds the old "highlight next click" checkbox into {@link ClickHighlight}, so turning the
 * highlight off is not reset by the upgrade.
 */
@Slf4j
@Singleton
class ClickHighlightMigration
{
	private final ConfigManager configManager;

	@Inject
	ClickHighlightMigration(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	void run()
	{
		if (configManager.getConfiguration(EasyTemporossConfig.GROUP, EasyTemporossConfig.CLICK_HIGHLIGHT_KEY) != null)
		{
			return;
		}

		String legacy = configManager.getConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.LEGACY_HIGHLIGHT_NEXT_CLICK_KEY);
		if (legacy == null)
		{
			return;
		}

		ClickHighlight highlight = fromLegacy(Boolean.parseBoolean(legacy));
		configManager.setConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.CLICK_HIGHLIGHT_KEY, highlight);
		configManager.unsetConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.LEGACY_HIGHLIGHT_NEXT_CLICK_KEY);
		log.debug("migrated highlight checkbox to {}", highlight);
	}

	static ClickHighlight fromLegacy(boolean enabled)
	{
		return enabled ? ClickHighlight.THIS_AND_NEXT : ClickHighlight.OFF;
	}
}

package com.easytempoross;

import lombok.Value;
import net.runelite.api.NPC;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;

@Value
class ClickTarget
{
	TileObject object;
	NPC npc;
	WorldPoint tile;

	static ClickTarget none()
	{
		return new ClickTarget(null, null, null);
	}

	static ClickTarget ofObject(TileObject object)
	{
		return new ClickTarget(object, null, object == null ? null : object.getWorldLocation());
	}

	static ClickTarget ofNpc(NPC npc)
	{
		return new ClickTarget(null, npc, npc == null ? null : npc.getWorldLocation());
	}

	static ClickTarget ofTile(WorldPoint tile)
	{
		return new ClickTarget(null, null, tile);
	}

	static ClickTarget objectAt(TileObject object, WorldPoint pathTile)
	{
		return new ClickTarget(object, null, pathTile);
	}

	static ClickTarget npcAt(NPC npc, WorldPoint pathTile)
	{
		return new ClickTarget(null, npc, pathTile);
	}

	boolean isEmpty()
	{
		return object == null && npc == null && tile == null;
	}

	boolean sameHighlightAs(ClickTarget other)
	{
		if (other == null || isEmpty() || other.isEmpty())
		{
			return false;
		}
		if (npc != null || other.npc != null)
		{
			return npc == other.npc;
		}
		if (object != null || other.object != null)
		{
			return object == other.object;
		}
		return tile != null && tile.equals(other.tile);
	}
}

package com.easytempoross;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(EasyTemporossConfig.GROUP)
public interface EasyTemporossConfig extends Config
{
	String GROUP = "jams-solo-tempoross";
	String PATH_DISPLAY_KEY = "pathDisplay";
	String PATH_PROVIDER_KEY = "pathProvider";
	String CLICK_HIGHLIGHT_KEY = "clickHighlight";
	/** Replaced by {@link #PATH_DISPLAY_KEY}; still read once by {@link PathDisplayMigration}. */
	String LEGACY_SHOW_PATH_KEY = "showPath";
	/** Replaced by {@link #PATH_DISPLAY_KEY}; still read once by {@link PathDisplayMigration}. */
	String LEGACY_SHOW_MINIMAP_PATH_KEY = "showMinimapPath";
	/** Replaced by {@link #CLICK_HIGHLIGHT_KEY}; still read once by {@link ClickHighlightMigration}. */
	String LEGACY_HIGHLIGHT_NEXT_CLICK_KEY = "highlightNextClick";

	@ConfigSection(
		name = "Helper",
		description = "Click-here solo Tempoross guidance",
		position = 0
	)
	String helperSection = "helper";

	@ConfigSection(
		name = "Sounds",
		description = "Plugin chimes, independent of the in-game sound-effect volume",
		position = 1
	)
	String soundsSection = "sounds";

	@ConfigSection(
		name = "Reminders",
		description = "Idle warning",
		position = 2
	)
	String reminderSection = "reminders";

	@ConfigSection(
		name = "Advanced",
		description = "Pick which game sound plays for each chime",
		position = 3,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = "enableHelper",
		name = "Enable helper",
		description = "Show the next-step overlay and status panel",
		section = helperSection,
		position = 0
	)
	default boolean enableHelper()
	{
		return true;
	}

	@ConfigItem(
		keyName = CLICK_HIGHLIGHT_KEY,
		name = "Click highlight",
		description = "This click outlines the current target. Next outlines the following destination (labelled Next) while you are already fishing, cooking, depositing, or harpooning the pool.",
		section = helperSection,
		position = 1
	)
	default ClickHighlight clickHighlight()
	{
		return ClickHighlight.THIS_AND_NEXT;
	}

	@ConfigItem(
		keyName = PATH_DISPLAY_KEY,
		name = "Path display",
		description = "Where to draw the path to your next destination. Click highlights are unaffected.",
		section = helperSection,
		position = 2
	)
	default PathDisplay pathDisplay()
	{
		return PathDisplay.FLOOR_AND_MINIMAP;
	}

	@ConfigItem(
		keyName = PATH_PROVIDER_KEY,
		name = "Path source",
		description = "Plugin lines draws this plugin's own path. Shortest Path hands the destination to the Shortest Path plugin instead, coloured by the current step, and falls back to plugin lines when that plugin is not running.",
		section = helperSection,
		position = 3
	)
	default PathProvider pathProvider()
	{
		return PathProvider.PLUGIN;
	}

	@ConfigItem(
		keyName = "showStatusPanel",
		name = "Show status panel",
		description = "Compact panel for the current step, fish counts, and energy",
		section = helperSection,
		position = 4
	)
	default boolean showStatusPanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showDepositCountdown",
		name = "Deposit countdown",
		description = "Large on-screen count of crate deposits left so you can AFK until it hits 0",
		section = helperSection,
		position = 5
	)
	default boolean showDepositCountdown()
	{
		return true;
	}

	@Range(min = 24, max = 96)
	@ConfigItem(
		keyName = "depositCountdownSize",
		name = "Countdown size",
		description = "Size of the deposit countdown once it reaches the last 3 deposits",
		section = helperSection,
		position = 6
	)
	default int depositCountdownSize()
	{
		return 48;
	}

	@ConfigItem(
		keyName = "replaceGameHud",
		name = "Replace game HUD",
		description = "Hide the default Tempoross bars and show energy, storm, and points in the status panel",
		section = helperSection,
		position = 7
	)
	default boolean replaceGameHud()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideSkillingOverlays",
		name = "Hide fishing and cooking overlays",
		description = "Hide RuneLite's fishing and cooking stat overlays while you are in a Tempoross game",
		section = helperSection,
		position = 8
	)
	default boolean hideSkillingOverlays()
	{
		return true;
	}

	@ConfigItem(
		keyName = "requireHarpoon",
		name = "Require harpoon",
		description = "When off, skip harpoon prep and recovery so you can fish barehanded (barbarian training)",
		section = helperSection,
		position = 9
	)
	default boolean requireHarpoon()
	{
		return true;
	}

	@ConfigItem(
		keyName = "depositChime",
		name = "Countdown chime",
		description = "Play a chime at 3, 2, and 1 deposits left, then a louder stop at 0",
		section = soundsSection,
		position = 0
	)
	default boolean depositChime()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chimeMode",
		name = "Final chime",
		description = "All Actions also plays the stop sound when fishing, cooking, filling, or the spirit pool finishes. Deposit Only keeps that sound on the crate countdown.",
		section = soundsSection,
		position = 1
	)
	default ChimeMode chimeMode()
	{
		return ChimeMode.ALL_ACTIONS;
	}

	@ConfigItem(
		keyName = "doubleFishChime",
		name = "Double-fish chime",
		description = "Play a soft cue when the helper wants the double fishing spot and your inventory still has space",
		section = soundsSection,
		position = 2
	)
	default boolean doubleFishChime()
	{
		return true;
	}

	@ConfigItem(
		keyName = "depositFireChime",
		name = "Deposit fire alert",
		description = "Play a sound when a fire forces you off the crate tile during a deposit",
		section = soundsSection,
		position = 3
	)
	default boolean depositFireChime()
	{
		return true;
	}

	@Range(max = 127)
	@ConfigItem(
		keyName = "soundVolume",
		name = "Sound volume",
		description = "Volume for plugin chimes (0–127). Independent of the game's sound-effect slider.",
		section = soundsSection,
		position = 4
	)
	default int soundVolume()
	{
		return 32;
	}

	@ConfigItem(
		keyName = "countdownTickSound",
		name = "Countdown tick sound",
		description = "Sound at 3, 2, and 1 deposits left",
		section = advancedSection,
		position = 0
	)
	default PluginSound countdownTickSound()
	{
		return PluginSound.UI_BOOP;
	}

	@ConfigItem(
		keyName = "stopChimeSound",
		name = "Stop chime sound",
		description = "Sound when the deposit countdown hits 0, and for Final chime (All Actions)",
		section = advancedSection,
		position = 1
	)
	default PluginSound stopChimeSound()
	{
		return PluginSound.BELL_DONG;
	}

	@ConfigItem(
		keyName = "doubleFishSound",
		name = "Double-fish sound",
		description = "Sound when the helper wants the double fishing spot",
		section = advancedSection,
		position = 2
	)
	default PluginSound doubleFishSound()
	{
		return PluginSound.GE_DING;
	}

	@ConfigItem(
		keyName = "depositFireSound",
		name = "Deposit fire sound",
		description = "Sound when a fire forces you off the crate tile",
		section = advancedSection,
		position = 3
	)
	default PluginSound depositFireSound()
	{
		return PluginSound.PRAYER_TWINKLE;
	}

	@Range(min = 3, max = 120)
	@ConfigItem(
		keyName = "idleReminderSeconds",
		name = "Idle reminder (seconds)",
		description = "Warn if you stand still at Tempoross this long",
		section = reminderSection,
		position = 0
	)
	default int idleReminderSeconds()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "idleFlash",
		name = "Idle screen tint",
		description = "Gently tint the screen when idle. Off by default.",
		section = reminderSection,
		position = 1
	)
	default boolean idleFlash()
	{
		return false;
	}
}

package com.easytempoross;

import com.google.inject.Provides;
import com.easytempoross.overlay.DepositCountdownOverlay;
import com.easytempoross.overlay.DepositFireTintOverlay;
import com.easytempoross.overlay.IdleTintOverlay;
import com.easytempoross.overlay.NextClickOverlay;
import com.easytempoross.overlay.PathMinimapOverlay;
import com.easytempoross.overlay.StatusOverlay;
import com.easytempoross.overlay.StormHurryOverlay;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Jam's Solo Tempoross",
	description = "Guided walkthrough of the 16/19/19 solo Tempoross rotation with click-here help, pathing, and recovery",
	tags = {"tempoross", "fishing", "solo", "minigame", "skilling", "helper"}
)
public class EasyTemporossPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NextClickOverlay nextClickOverlay;

	@Inject
	private PathMinimapOverlay pathMinimapOverlay;

	@Inject
	private StatusOverlay statusOverlay;

	@Inject
	private DepositCountdownOverlay depositCountdownOverlay;

	@Inject
	private StormHurryOverlay stormHurryOverlay;

	@Inject
	private DepositFireTintOverlay depositFireTintOverlay;

	@Inject
	private IdleTintOverlay idleTintOverlay;

	@Inject
	private RotationHelper rotationHelper;

	@Inject
	private SceneTracker sceneTracker;

	@Inject
	private WaveTracker waveTracker;

	@Inject
	private PathDisplayMigration pathDisplayMigration;

	@Inject
	private ClickHighlightMigration clickHighlightMigration;

	@Inject
	private ShortestPathBridge shortestPathBridge;

	@Override
	protected void startUp()
	{
		pathDisplayMigration.run();
		clickHighlightMigration.run();
		rotationHelper.reset();
		sceneTracker.reset();
		sceneTracker.scanScene();
		overlayManager.add(nextClickOverlay);
		overlayManager.add(pathMinimapOverlay);
		overlayManager.add(statusOverlay);
		overlayManager.add(depositCountdownOverlay);
		overlayManager.add(stormHurryOverlay);
		overlayManager.add(depositFireTintOverlay);
		overlayManager.add(idleTintOverlay);
		log.debug("Jam's Solo Tempoross started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(nextClickOverlay);
		overlayManager.remove(pathMinimapOverlay);
		overlayManager.remove(statusOverlay);
		overlayManager.remove(depositCountdownOverlay);
		overlayManager.remove(stormHurryOverlay);
		overlayManager.remove(depositFireTintOverlay);
		overlayManager.remove(idleTintOverlay);
		rotationHelper.reset();
		sceneTracker.reset();
		shortestPathBridge.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!EasyTemporossConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		String key = event.getKey();
		if (EasyTemporossConfig.PATH_DISPLAY_KEY.equals(key)
			|| EasyTemporossConfig.PATH_PROVIDER_KEY.equals(key))
		{
			shortestPathBridge.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		rotationHelper.update();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		sceneTracker.onSpawn(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		sceneTracker.onDespawn(event.getGameObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		sceneTracker.onSpawn(event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		sceneTracker.onDespawn(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		sceneTracker.onSpawn(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		sceneTracker.onDespawn(event.getGroundObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		sceneTracker.onSpawn(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		sceneTracker.onDespawn(event.getWallObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		sceneTracker.onNpcSpawn(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		// Same index, new id — e.g. a normal spot transforms into the SPECIAL double.
		sceneTracker.onNpcSpawn(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		sceneTracker.onNpcDespawn(event.getNpc());
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.TEMPOROSS_TETHERED)
		{
			waveTracker.setTethered(event.getValue() > 0);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		waveTracker.onChatMessage(event);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			sceneTracker.reset();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			sceneTracker.scanScene();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			rotationHelper.reset();
			sceneTracker.reset();
		}
	}

	@Provides
	EasyTemporossConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EasyTemporossConfig.class);
	}
}

package com.easytempoross;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

@Singleton
public class GameHud
{
	private static final Pattern DIGITS = Pattern.compile("(\\d+)");

	private final Client client;

	@Getter
	private int energy = -1;
	@Getter
	private int intensity = -1;
	@Getter
	private int essence = -1;
	@Getter
	private int points = -1;

	private boolean hidDefaultHud;

	@Inject
	GameHud(Client client)
	{
		this.client = client;
	}

	public void reset()
	{
		restoreDefaultHud();
		clearValues();
	}

	/** The Tempoross HUD interface is loaded, even if we hid it ourselves. */
	public boolean isPresent()
	{
		return client.getWidget(InterfaceID.TemporossHud.CONTENT) != null;
	}

	/** Whether the vanilla HUD is currently shown on screen. */
	public boolean isVisible()
	{
		Widget content = client.getWidget(InterfaceID.TemporossHud.CONTENT);
		return content != null && !content.isHidden();
	}

	public void update()
	{
		if (!isPresent())
		{
			if (!hidDefaultHud)
			{
				clearValues();
			}
			return;
		}
		energy = readBar(
			InterfaceID.TemporossHud.ENERGY_TITLE,
			InterfaceID.TemporossHud.ENERGY,
			InterfaceID.TemporossHud.ENERGY_BAR,
			InterfaceID.TemporossHud.ENERGY_BAR_BACK);
		essence = readBar(
			InterfaceID.TemporossHud.ESSENCE_TITLE,
			InterfaceID.TemporossHud.ESSENCE,
			InterfaceID.TemporossHud.ESSENCE_BAR,
			InterfaceID.TemporossHud.ESSENCE_BAR_BACK);
		intensity = readBar(
			InterfaceID.TemporossHud.STORM_INTENSITY_TITLE,
			InterfaceID.TemporossHud.STORM_INTENSITY,
			InterfaceID.TemporossHud.STORM_INTENSITY_BAR,
			InterfaceID.TemporossHud.STORM_INTENSITY_BAR_BACK);
		points = parseText(InterfaceID.TemporossHud.POINTS_TEXT);
	}

	/**
	 * Hides the vanilla Tempoross bar panel so our status overlay can show the same numbers.
	 */
	void applyReplacement(boolean replace)
	{
		if (!isPresent())
		{
			restoreDefaultHud();
			return;
		}
		if (replace)
		{
			setDefaultHudHidden(true);
		}
		else
		{
			restoreDefaultHud();
		}
	}

	private void restoreDefaultHud()
	{
		if (hidDefaultHud)
		{
			setDefaultHudHidden(false);
		}
	}

	private void setDefaultHudHidden(boolean hidden)
	{
		Widget content = client.getWidget(InterfaceID.TemporossHud.CONTENT);
		if (content == null)
		{
			return;
		}
		content.setHidden(hidden);
		hidDefaultHud = hidden;
	}

	private void clearValues()
	{
		energy = -1;
		intensity = -1;
		essence = -1;
		points = -1;
	}

	/**
	 * Reads a Tempoross HUD bar percentage from its title label, falling back to the vanilla
	 * bar widget width if the label has no parseable text.
	 */
	private int readBar(int titleComponent, int layerComponent, int fillComponent, int backComponent)
	{
		int fromTitle = parseText(titleComponent);
		if (fromTitle >= 0)
		{
			return fromTitle;
		}
		int fromLayer = parseText(layerComponent);
		if (fromLayer >= 0)
		{
			return fromLayer;
		}
		return readBarWidth(fillComponent, backComponent);
	}

	private int parseText(int component)
	{
		return parseWidget(client.getWidget(component));
	}

	private int readBarWidth(int fillComponent, int backComponent)
	{
		Widget fill = client.getWidget(fillComponent);
		Widget back = client.getWidget(backComponent);
		if (fill == null || back == null)
		{
			return -1;
		}
		int backWidth = back.getWidth();
		if (backWidth <= 0)
		{
			return -1;
		}
		return Math.min(100, Math.max(0, fill.getWidth() * 100 / backWidth));
	}

	private int parseWidget(Widget widget)
	{
		if (widget == null)
		{
			return -1;
		}
		int value = firstNumber(widget.getText());
		if (value >= 0)
		{
			return value;
		}
		Widget[] children = widget.getChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				value = parseWidget(child);
				if (value >= 0)
				{
					return value;
				}
			}
		}
		Widget[] dynamic = widget.getDynamicChildren();
		if (dynamic != null)
		{
			for (Widget child : dynamic)
			{
				value = parseWidget(child);
				if (value >= 0)
				{
					return value;
				}
			}
		}
		return -1;
	}

	static int firstNumber(String text)
	{
		if (text == null || text.isEmpty())
		{
			return -1;
		}
		Matcher matcher = DIGITS.matcher(text);
		if (!matcher.find())
		{
			return -1;
		}
		try
		{
			return Integer.parseInt(matcher.group(1));
		}
		catch (NumberFormatException ex)
		{
			return -1;
		}
	}
}

package com.easytempoross;

import lombok.Builder;
