package com.easytempoross;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

@Singleton
public class IdleReminder
{
	private final Client client;
	private final EasyTemporossConfig config;

	@Getter
	private final List<String> warnings = new ArrayList<>();

	@Getter
	private boolean idle;

	private Instant lastMoveAt = Instant.now();
	private WorldPoint lastTile;

	@Inject
	IdleReminder(Client client, EasyTemporossConfig config)
	{
		this.client = client;
		this.config = config;
	}

	public void reset()
	{
		warnings.clear();
		idle = false;
		lastMoveAt = Instant.now();
		lastTile = null;
	}

	public void update(boolean inContent)
	{
		warnings.clear();
		idle = false;
		if (!inContent)
		{
			return;
		}
		updateIdle();
		if (idle)
		{
			warnings.add("Idle — click the highlight");
		}
	}

	private void updateIdle()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		if (player.getAnimation() != -1 || player.getPoseAnimation() != player.getIdlePoseAnimation())
		{
			lastTile = player.getWorldLocation();
			lastMoveAt = Instant.now();
			idle = false;
			return;
		}
		WorldPoint now = player.getWorldLocation();
		if (lastTile == null || now == null || lastTile.distanceTo(now) > 0)
		{
			lastTile = now;
			lastMoveAt = Instant.now();
			idle = false;
			return;
		}
		idle = Duration.between(lastMoveAt, Instant.now()).getSeconds() >= config.idleReminderSeconds();
	}
}

package com.easytempoross;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Tempoross is built as an instance, so the tiles shown on the world map are not the tiles the
 * client reports for scene entities. Every hardcoded tile in {@link RotationConstants} is a
 * world-map tile and has to be translated before it can be compared against anything that came
 * out of the scene, and vice versa.
 */
@Singleton
class InstanceCoords
{
	private final Client client;
	private final Map<WorldPoint, WorldPoint> sceneCache = new HashMap<>();
	private int cachedTick = -1;

	@Inject
	InstanceCoords(Client client)
	{
		this.client = client;
	}

	/**
	 * Translates a world-map tile into the matching tile in the loaded scene, or null when that
	 * tile is not currently loaded.
	 */
	WorldPoint scene(WorldPoint template)
	{
		if (template == null)
		{
			return null;
		}
		int tick = client.getTickCount();
		if (tick != cachedTick)
		{
			sceneCache.clear();
			cachedTick = tick;
		}
		if (sceneCache.containsKey(template))
		{
			return sceneCache.get(template);
		}
		WorldPoint resolved = resolve(template);
		sceneCache.put(template, resolved);
		return resolved;
	}

	/** Translates a scene tile back to the tile it is drawn from on the world map. */
	WorldPoint template(WorldPoint scene)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (scene == null || worldView == null)
		{
			return scene;
		}
		if (!worldView.isInstance())
		{
			return scene;
		}
		LocalPoint local = LocalPoint.fromWorld(worldView, scene);
		return local == null ? null : WorldPoint.fromLocalInstance(client, local);
	}

	boolean isNorthShore(WorldPoint scene)
	{
		return isNorthShore(scene, null);
	}

	/**
	 * North-shore test with a LocalPoint fallback when the scene tile cannot be mapped through
	 * {@link LocalPoint#fromWorld} (common for far-edge fishing spots).
	 */
	boolean isNorthShore(WorldPoint scene, LocalPoint local)
	{
		return WorkArea.isNorthShore(mapToTemplate(scene, local));
	}

	/**
	 * Maps a scene tile to its world-map template tile. Prefers the entity's {@link LocalPoint}
	 * when available — {@link LocalPoint#fromWorld} can return a wrong non-null mapping for
	 * far-edge tiles, which would skip any later local fallback.
	 */
	WorldPoint mapToTemplate(WorldPoint scene, LocalPoint local)
	{
		if (local != null)
		{
			WorldPoint fromLocal = WorldPoint.fromLocalInstance(client, local);
			if (fromLocal != null)
			{
				return fromLocal;
			}
		}
		return template(scene);
	}

	private WorldPoint resolve(WorldPoint template)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}
		if (!worldView.isInstance())
		{
			return LocalPoint.fromWorld(worldView, template) == null ? null : template;
		}
		Player player = client.getLocalPlayer();
		WorldPoint anchor = player == null ? null : player.getWorldLocation();
		WorldPoint best = null;
		int bestDist = Integer.MAX_VALUE;
		for (WorldPoint candidate : WorldPoint.toLocalInstance(worldView, template))
		{
			if (candidate == null || LocalPoint.fromWorld(worldView, candidate) == null)
			{
				continue;
			}
			int dist = anchor == null ? 0 : candidate.distanceTo(anchor);
			if (dist < bestDist)
			{
				bestDist = dist;
				best = candidate;
			}
		}
		return best;
	}
}

package com.easytempoross;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;

@Singleton
public class InventoryChecker
{
	private static final int INVENTORY_SIZE = 28;

	private final Client client;

	@Inject
	InventoryChecker(Client client)
	{
		this.client = client;
	}

	public InventorySnapshot scan()
	{
		int raw = 0;
		int cooked = 0;
		int crystal = 0;
		int emptyBuckets = 0;
		int waterBuckets = 0;
		int empty = 0;
		boolean harpoon = false;
		boolean hammer = false;
		boolean imcando = false;
		boolean rope = false;

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			empty = INVENTORY_SIZE;
		}
		else
		{
			Item[] items = inventory.getItems();
			for (int i = 0; i < INVENTORY_SIZE; i++)
			{
				Item item = i < items.length ? items[i] : null;
				if (item == null || item.getId() < 0)
				{
					empty++;
					continue;
				}
				int id = item.getId();
				int qty = Math.max(1, item.getQuantity());
				if (id == ItemID.TEMPOROSS_RAW_HARPOONFISH)
				{
					raw += qty;
				}
				else if (id == ItemID.TEMPOROSS_HARPOONFISH)
				{
					cooked += qty;
				}
				else if (id == ItemID.TEMPOROSS_CRYSTALLISED_HARPOONFISH)
				{
					crystal += qty;
				}
				else if (id == ItemID.BUCKET_EMPTY)
				{
					emptyBuckets += qty;
				}
				else if (id == ItemID.BUCKET_WATER)
				{
					waterBuckets += qty;
				}
				else if (id == ItemID.ROPE)
				{
					rope = true;
				}
				else if (id == ItemID.HAMMER)
				{
					hammer = true;
				}
				else if (id == ItemID.IMCANDO_HAMMER || id == ItemID.IMCANDO_HAMMER_OFFHAND)
				{
					imcando = true;
				}
				else if (TemporossIds.isHarpoon(id))
				{
					harpoon = true;
				}
			}
		}

		boolean hat = false;
		boolean top = false;
		boolean legs = false;
		boolean boots = false;
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			if (isSlot(worn, EquipmentInventorySlot.WEAPON, TemporossIds::isHarpoon))
			{
				harpoon = true;
			}
			if (isSlotId(worn, EquipmentInventorySlot.WEAPON, ItemID.IMCANDO_HAMMER)
				|| isSlotId(worn, EquipmentInventorySlot.SHIELD, ItemID.IMCANDO_HAMMER_OFFHAND)
				|| isSlotId(worn, EquipmentInventorySlot.SHIELD, ItemID.IMCANDO_HAMMER))
			{
				imcando = true;
			}
			hat = isSlotId(worn, EquipmentInventorySlot.HEAD, ItemID.SPIRIT_ANGLER_HAT);
			top = isSlotId(worn, EquipmentInventorySlot.BODY, ItemID.SPIRIT_ANGLER_TOP);
			legs = isSlotId(worn, EquipmentInventorySlot.LEGS, ItemID.SPIRIT_ANGLER_LEGS);
			boots = isSlotId(worn, EquipmentInventorySlot.BOOTS, ItemID.SPIRIT_ANGLER_BOOTS);
		}

		return new InventorySnapshot(
			raw,
			cooked,
			crystal,
			emptyBuckets,
			waterBuckets,
			empty,
			harpoon,
			hammer,
			imcando,
			rope,
			hat && top && legs && boots);
	}

	private static boolean isSlotId(ItemContainer worn, EquipmentInventorySlot slot, int id)
	{
		Item item = worn.getItem(slot.getSlotIdx());
		return item != null && item.getId() == id;
	}

	private interface IdMatch
	{
		boolean test(int id);
	}

	private static boolean isSlot(ItemContainer worn, EquipmentInventorySlot slot, IdMatch match)
	{
		Item item = worn.getItem(slot.getSlotIdx());
		return item != null && match.test(item.getId());
	}
}

package com.easytempoross;

import lombok.Value;

@Value
public class InventorySnapshot
{
	int rawFish;
	int cookedFish;
	int crystalFish;
	int emptyBuckets;
	int waterBuckets;
	int emptySlots;
	boolean hasHarpoon;
	boolean hasHammer;
	boolean hasImcando;
	boolean hasRope;
	boolean spiritAnglerComplete;

	public int getTotalFish()
	{
		return rawFish + cookedFish + crystalFish;
	}

	public int getDumpableFish()
	{
		return cookedFish + crystalFish;
	}

	public int getBuckets()
	{
		return emptyBuckets + waterBuckets;
	}

	public boolean hasHammerTool()
	{
		return hasHammer || hasImcando;
	}

	public boolean hasRopeOrOutfit()
	{
		return hasRope || spiritAnglerComplete;
	}

	public boolean toolsReady()
	{
		return hasHarpoon && hasRopeOrOutfit() && getBuckets() >= RotationConstants.BUCKETS_NEEDED;
	}
}

package com.easytempoross;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Temporarily removes RuneLite skilling overlays that stack on top of our status panel.
 */
@Singleton
class OverlaySuppressor
{
	private static final Set<String> TARGETS = new HashSet<>(Arrays.asList(
		"FishingOverlay",
		"CookingOverlay"
	));

	private final OverlayManager overlayManager;
	private final List<Overlay> suppressed = new ArrayList<>();

	@Inject
	OverlaySuppressor(OverlayManager overlayManager)
	{
		this.overlayManager = overlayManager;
	}

	void update(boolean active)
	{
		if (active)
		{
			if (suppressed.isEmpty())
			{
				overlayManager.removeIf(overlay ->
				{
					if (TARGETS.contains(overlay.getName()))
					{
						suppressed.add(overlay);
						return true;
					}
					return false;
				});
			}
		}
		else
		{
			restore();
		}
	}

	void reset()
	{
		restore();
	}

	private void restore()
	{
		for (Overlay overlay : suppressed)
		{
			overlayManager.add(overlay);
		}
		suppressed.clear();
	}
}

