package com.easytempoross;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Folds the old "show path on floor" and "show path on minimap" checkboxes into the single
 * {@link PathDisplay} dropdown, so upgrading does not silently reset either choice.
 */
@Slf4j
@Singleton
class PathDisplayMigration
{
	private final ConfigManager configManager;

	@Inject
	PathDisplayMigration(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	void run()
	{
		if (configManager.getConfiguration(EasyTemporossConfig.GROUP, EasyTemporossConfig.PATH_DISPLAY_KEY) != null)
		{
			return;
		}

		String floor = configManager.getConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.LEGACY_SHOW_PATH_KEY);
		String minimap = configManager.getConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.LEGACY_SHOW_MINIMAP_PATH_KEY);
		if (floor == null && minimap == null)
		{
			return;
		}

		PathDisplay display = displayFor(enabled(floor), enabled(minimap));
		configManager.setConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.PATH_DISPLAY_KEY, display);
		configManager.unsetConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.LEGACY_SHOW_PATH_KEY);
		configManager.unsetConfiguration(
			EasyTemporossConfig.GROUP, EasyTemporossConfig.LEGACY_SHOW_MINIMAP_PATH_KEY);
		log.debug("migrated path checkboxes to {}", display);
	}

	static PathDisplay displayFor(boolean floor, boolean minimap)
	{
		if (floor && minimap)
		{
			return PathDisplay.FLOOR_AND_MINIMAP;
		}
		if (floor)
		{
			return PathDisplay.FLOOR;
		}
		if (minimap)
		{
			return PathDisplay.MINIMAP;
		}
		return PathDisplay.OFF;
	}

	/** Both checkboxes defaulted to on, so an absent key means the user never turned it off. */
	private static boolean enabled(String value)
	{
		return value == null || Boolean.parseBoolean(value);
	}
}

package com.easytempoross;

import java.util.List;
import net.runelite.api.coords.WorldPoint;

/**
 * When a previously computed walk can be kept. Reusing a path after you have stepped off it
 * draws a V: from your new tile, back to the old waypoint, then on to the destination.
 */
final class PathPolicy
{
	static final int DRIFT_TILES = 1;
	static final int DETOUR_SLACK = 4;

	private PathPolicy()
	{
	}

	static int nearestIndex(List<WorldPoint> path, WorldPoint start)
	{
		int nearest = 0;
		int best = Integer.MAX_VALUE;
		for (int i = 0; i < path.size(); i++)
		{
			int d = path.get(i).distanceTo(start);
			if (d < best)
			{
				best = d;
				nearest = i;
			}
		}
		return nearest;
	}

	static boolean canReuse(WorldPoint start, WorldPoint end, List<WorldPoint> cached)
	{
		if (start == null || end == null || cached == null || cached.size() < 2)
		{
			return false;
		}
		int nearest = nearestIndex(cached, start);
		if (nearest >= cached.size() - 1)
		{
			return false;
		}
		int dist = cached.get(nearest).distanceTo(start);
		if (dist > DRIFT_TILES)
		{
			return false;
		}
		WorldPoint first = cached.get(nearest);
		if (first.distanceTo(end) > start.distanceTo(end))
		{
			return false;
		}
		int via = start.distanceTo(first) + polylineLength(cached, nearest);
		return via <= start.distanceTo(end) + DETOUR_SLACK;
	}

	static int polylineLength(List<WorldPoint> path, int from)
	{
		int length = 0;
		for (int i = from; i < path.size() - 1; i++)
		{
			length += path.get(i).distanceTo(path.get(i + 1));
		}
		return length;
	}
}

