			}
			if (!TemporossIds.isWestHost(npc.getId()) && !coords.isNorthShore(npc.getWorldLocation()))
			{
				continue;
			}
			int dist = from == null ? 0 : npc.getWorldLocation().distanceTo(from);
			if (dist < bestDist)
			{
				bestDist = dist;
				best = npc;
			}
