			}
			WorldPoint fire = npc.getWorldLocation();
			if (origin != null && fire.distanceTo(origin) > tiles)
			{
				continue;
			}
			int dist = player == null ? 0 : fire.distanceTo(player);
			if (dist < bestDist)
			{
				bestDist = dist;
				best = npc;
			}
		}
		return best;
	}

