	static int distanceTo(TileObject object, WorldPoint loc)
	{
		if (object == null || loc == null)
		{
			return Integer.MAX_VALUE;
		}
		if (object instanceof GameObject)
		{
			GameObject go = (GameObject) object;
			WorldArea area = new WorldArea(go.getWorldLocation(), Math.max(1, go.sizeX()), Math.max(1, go.sizeY()));
			return area.distanceTo(loc);
		}
		return object.getWorldLocation().distanceTo(loc);
	}

	private NPC nearestNpc(WorldPoint from, WorkArea area, NpcMatch match)
	{
		NPC best = null;
		int bestDist = Integer.MAX_VALUE;
		for (NPC npc : npcs.values())
		{
			if (npc == null || npc.getWorldLocation() == null || !match.test(npc))
			{
				continue;
			}
			if (!onSide(area, npc.getWorldLocation()))
			{
				continue;
			}
			int dist = from == null ? 0 : npc.getWorldLocation().distanceTo(from);
			if (dist < bestDist)
			{
				bestDist = dist;
				best = npc;
			}
		}
		return best;
	}

	private TileObject closestObject(WorkArea area, WorldPoint hint, ObjectMatch match)
	{
		TileObject best = null;
		int bestDist = Integer.MAX_VALUE;
		for (TileObject object : objects)
		{
			if (object == null || !match.test(object))
			{
				continue;
			}
			if (!onSide(area, object.getWorldLocation()))
			{
				continue;
			}
			int dist = distTo(object, hint);
			if (dist < bestDist)
			{
				bestDist = dist;
				best = object;
			}
		}
		return best;
	}

	private int distTo(TileObject object, WorldPoint hint)
	{
		if (object == null)
		{
			return Integer.MAX_VALUE;
		}
		LocalPoint objLocal = object.getLocalLocation();
		WorldView worldView = client.getTopLevelWorldView();
		LocalPoint hintLocal = hint == null || worldView == null
			? null
			: LocalPoint.fromWorld(worldView, hint);
		if (objLocal != null && hintLocal != null)
		{
			return objLocal.distanceTo(hintLocal);
		}
		return distanceTo(object, hint);
	}

	private boolean onSide(WorkArea area, WorldPoint point)
	{
		return area == null || coords.isNorthShore(point);
	}

	/**
	 * Regular north spots need a Harpoon action. The SPECIAL double is accepted by id alone so
	 * far-edge spots without loaded actions still win when preferDouble is on.
	 */
	private static boolean isFishableSpot(NPC npc, boolean preferDouble)
	{
		if (npc == null)
		{
			return false;
		}
		if (preferDouble && TemporossIds.isDoubleSpot(npc.getId()))
		{
			return true;
		}
		return TemporossIds.isHarpoonSpot(npc);
	}

	private boolean isOurFishingSpot(NPC npc)
	{
		if (npc == null || npc.getWorldLocation() == null || TemporossIds.isSouthFishingSpot(npc.getId()))
		{
			return false;
		}
		WorldPoint mapped = coords.mapToTemplate(npc.getWorldLocation(), npc.getLocalLocation());
		if (mapped != null && WorkArea.isNorthShore(mapped))
		{
			return true;
		}
		if (!TemporossIds.isDoubleSpot(npc.getId()))
		{
			return false;
		}
		// Far SPECIAL tiles often map wrong or not at all — trust proximity to the north shrine.
		WorldPoint north = coords.scene(RotationConstants.NORTH_SHRINE);
		return north != null && npc.getWorldLocation().distanceTo(north) <= RotationConstants.FIRE_ISLAND_TILES * 2;
	}

	private boolean sameCoveSide(WorldPoint from, WorldPoint point)
	{
		if (from == null || point == null)
		{
			return true;
		}
		return coords.isNorthShore(from) == coords.isNorthShore(point);
	}

	private boolean isOurWorkFire(WorkArea area, NPC npc)
	{
		if (npc == null || npc.getWorldLocation() == null)
		{
			return false;
		}
		if (!TemporossIds.isFireNpc(npc.getId()) && !TemporossIds.hasAction(npc, "Douse"))
		{
			return false;
		}
		WorldPoint fire = npc.getWorldLocation();
		if (area == null)
		{
			return coords.isNorthShore(fire);
		}
		return area.isOurSide(fire);
	}

	private boolean isOurWorkLocation(WorkArea area, WorldPoint point)
	{
		if (area == null)
		{
			return true;
		}
		return area.isOurSide(point);
	}

	private void scanTile(Tile tile)
	{
		if (tile == null)
		{
			return;
		}
		GameObject[] gameObjects = tile.getGameObjects();
		if (gameObjects != null)
		{
			for (GameObject object : gameObjects)
			{
				onSpawn(object);
			}
		}
		DecorativeObject deco = tile.getDecorativeObject();
		if (deco != null)
		{
			onSpawn(deco);
		}
		GroundObject ground = tile.getGroundObject();
		if (ground != null)
		{
			onSpawn(ground);
		}
		WallObject wall = tile.getWallObject();
		if (wall != null)
		{
			onSpawn(wall);
		}
	}

	private void assignDockObject(TileObject object, boolean despawn)
	{
		int id = object.getId();
		if (id == TemporossIds.DOCK_PUMP)
		{
			dockPump = despawn ? clear(dockPump, object) : prefer(dockPump, object);
		}
		else if (TemporossIds.isSoloLadder(id))
		{
			soloLadder = despawn ? clear(soloLadder, object) : prefer(soloLadder, object);
		}
		else if (TemporossIds.isBucketCrate(id))
		{
			bucketCrate = despawn ? clear(bucketCrate, object) : prefer(bucketCrate, object);
		}
		else if (TemporossIds.isRopeCrate(id))
		{
			ropeCrate = despawn ? clear(ropeCrate, object) : prefer(ropeCrate, object);
		}
		else if (TemporossIds.isHammerCrate(id))
		{
			hammerCrate = despawn ? clear(hammerCrate, object) : prefer(hammerCrate, object);
		}
		else if (TemporossIds.isHarpoonCrate(id))
		{
			harpoonCrate = despawn ? clear(harpoonCrate, object) : prefer(harpoonCrate, object);
		}
	}

	private static TileObject clear(TileObject current, TileObject gone)
	{
		return current == gone ? null : current;
	}

	private static TileObject prefer(TileObject current, TileObject next)
	{
		return current == null ? next : current;
	}

	private Iterable<NPC> liveNpcs()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null || worldView.npcs() == null)
		{
			return npcs.values();
		}
		List<NPC> live = new ArrayList<>();
		for (NPC npc : worldView.npcs())
		{
			live.add(npc);
		}
		return live;
	}

	private interface NpcMatch
	{
		boolean test(NPC npc);
	}

	private interface ObjectMatch
	{
		boolean test(TileObject object);
	}
}

package com.easytempoross;

import java.awt.Color;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/**
 * Hands the next destination to the Shortest Path plugin over the event bus, tinted with the
 * current step's colour. Shortest Path cannot be a compile-time dependency of a hub plugin, so the
 * whole integration is fire-and-forget {@link PluginMessage}.
 */
@Slf4j
@Singleton
class ShortestPathBridge
{
	private static final String NAMESPACE = "shortestpath";
	private static final String MESSAGE_PATH = "path";
	private static final String MESSAGE_CLEAR = "clear";
	private static final String MESSAGE_START = "start";
	private static final String MESSAGE_TARGET = "target";
	private static final String MESSAGE_CONFIG = "config";
	private static final String PLUGIN_NAME = "Shortest Path";

	/**
	 * Shortest Path drops the target once you are within its own finish distance (5 tiles by
	 * default), which is well inside a single Tempoross hop. Re-posting on a slow tick keeps the
	 * line alive without asking it to recalculate every frame.
	 */
	private static final int REFRESH_TICKS = 5;

	private final Client client;
	private final EasyTemporossConfig config;
	private final EventBus eventBus;
	private final PluginManager pluginManager;
	private final InstanceCoords coords;

	private WorldPoint postedTarget;
	private Color postedColor;
	private PathDisplay postedDisplay;
	private int postedTick;

	@Inject
	ShortestPathBridge(
		Client client,
		EasyTemporossConfig config,
		EventBus eventBus,
		PluginManager pluginManager,
		InstanceCoords coords)
	{
		this.client = client;
		this.config = config;
		this.eventBus = eventBus;
		this.pluginManager = pluginManager;
		this.coords = coords;
	}

	/** True when Shortest Path is picked and actually running, so it owns the path drawing. */
	boolean isDriving()
	{
		return config.pathProvider() == PathProvider.SHORTEST_PATH && isShortestPathRunning();
	}

	void update(WorldPoint destination, Color color)
	{
		PathDisplay display = config.pathDisplay();
		if (!isDriving() || display.isOff() || destination == null)
		{
			clear();
			return;
		}

		Player player = client.getLocalPlayer();
		WorldPoint start = player == null ? null : coords.template(player.getWorldLocation());
		WorldPoint target = coords.template(destination);
		if (start == null || target == null)
		{
			return;
		}

		int tick = client.getTickCount();
		boolean sameTarget = target.equals(postedTarget);
		boolean unchanged = sameTarget && display == postedDisplay && Objects.equals(color, postedColor);
		if (unchanged && tick - postedTick < REFRESH_TICKS)
		{
			return;
		}

		if (!sameTarget)
		{
			log.debug("shortest path target {} -> {} (from {})", postedTarget, target, start);
		}

		postedTarget = target;
		postedColor = color;
		postedDisplay = display;
		postedTick = tick;

		Map<String, Object> data = new HashMap<>();
		data.put(MESSAGE_START, start);
		data.put(MESSAGE_TARGET, target);
		data.put(MESSAGE_CONFIG, overrides(display, color));
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_PATH, data));
	}

	/** Drops our path and hands Shortest Path's own colours back to the user. */
	void clear()
	{
		if (postedTarget == null)
		{
			return;
		}
		postedTarget = null;
		postedColor = null;
		postedDisplay = null;
		postedTick = 0;
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_CLEAR));
	}

	/**
	 * Keys match Shortest Path's own config keys. Every path message replaces the whole override
	 * map, so this has to be complete each time.
	 */
	private static Map<String, Object> overrides(PathDisplay display, Color color)
	{
		Map<String, Object> overrides = new HashMap<>();
		overrides.put("colourPath", color);
		overrides.put("colourPathCalculating", color);
		overrides.put("pathStyle", "Lines");
		overrides.put("showTileCounter", "Disabled");
		overrides.put("drawTiles", display.showsFloor());
		overrides.put("drawMinimap", display.showsMinimap());
		overrides.put("drawMap", false);
		overrides.put("drawTransports", false);
		overrides.put("showTransportInfo", false);
		return overrides;
	}

	private boolean isShortestPathRunning()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (PLUGIN_NAME.equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}
}

package com.easytempoross;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

final class TemporossArea
{
	private TemporossArea()
	{
	}

	static boolean isInMinigame(Client client)
	{
		if (client == null)
		{
			return false;
		}
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null || !worldView.isInstance())
		{
			return false;
		}
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		WorldPoint loc = WorldPoint.fromLocalInstance(client, player.getLocalLocation());
		if (loc == null || loc.getRegionID() != RotationConstants.TEMPOROSS_REGION)
		{
			return false;
		}
		return client.getWidget(InterfaceID.TemporossHud.CONTENT) != null;
	}

	static boolean isAtUnkah(Client client, TileObject soloLadder, TileObject dockPump)
	{
		if (isInMinigame(client))
		{
			return false;
		}
		if (soloLadder != null || dockPump != null)
		{
			return true;
		}
		Widget lobby = client.getWidget(InterfaceID.TemporossLobbyHud.CONTENT);
		return lobby != null && !lobby.isHidden();
	}

	static boolean isOnShip(WorldPoint player, TileObject mast, TileObject shipPump)
	{
		if (player == null)
		{
			return false;
		}
		if (mast != null && mast.getWorldLocation() != null && player.distanceTo(mast.getWorldLocation()) <= 8)
		{
			return true;
		}
		return shipPump != null && shipPump.getWorldLocation() != null
			&& player.distanceTo(shipPump.getWorldLocation()) <= 6;
	}

	static boolean isOnIsland(WorldPoint player, TileObject shrine, TileObject totem)
	{
		if (player == null)
		{
			return false;
		}
		if (shrine != null && shrine.getWorldLocation() != null && player.distanceTo(shrine.getWorldLocation()) <= 24)
		{
			return true;
		}
		return totem != null && totem.getWorldLocation() != null
			&& player.distanceTo(totem.getWorldLocation()) <= 16;
	}
}

package com.easytempoross;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.TileObject;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;

/**
 * Tempoross IDs. Gameval first; a few objects still only exist on the
 * deprecated {@link net.runelite.api.ObjectID} names.
 */
final class TemporossIds
{
	static final int[] FISHING_SPOTS = {
		NpcID.TEMPOROSS_HARPOONFISH_FISHINGSPOT_NORTH,
		NpcID.TEMPOROSS_HARPOONFISH_FISHINGSPOT_SOUTH,
		NpcID.TEMPOROSS_HARPOONFISH_FISHINGSPOT_SPECIAL
	};

	static final int DOUBLE_SPOT = NpcID.TEMPOROSS_HARPOONFISH_FISHINGSPOT_SPECIAL;
	static final int SPIRIT_POOL = NpcID.TEMPOROSS_P2_FISHINGSPOT;

	static final int[] AMMO_CRATES = {
		NpcID.TEMPOROSS_NPC_CRATE_AMMUNITION_1,
		NpcID.TEMPOROSS_NPC_CRATE_AMMUNITION_2,
		NpcID.TEMPOROSS_NPC_CRATE_AMMUNITION_3,
		NpcID.TEMPOROSS_NPC_CRATE_AMMUNITION_4
	};

	static final int[] FIRES = {
		NpcID.TEMPOROSS_FIRE_HITBOX,
		NpcID.TEMPOROSS_FIRE_TARGET_NPC
	};

	static final int[] HOSTS = {
		NpcID.TEMPOROSS_INSTANCE_HOST_E,
		NpcID.TEMPOROSS_INSTANCE_HOST_W,
		NpcID.TEMPOROSS_INSTANCE_HOST_N,
		NpcID.TEMPOROSS_INSTANCE_HOST_S,
		NpcID.TEMPOROSS_INSTANCE_HOST_E_VICTORY,
		NpcID.TEMPOROSS_INSTANCE_HOST_W_VICTORY,
		NpcID.TEMPOROSS_INSTANCE_HOST_N_VICTORY,
		NpcID.TEMPOROSS_INSTANCE_HOST_S_VICTORY
	};

	static final int[] VICTORY_HOSTS = {
		NpcID.TEMPOROSS_INSTANCE_HOST_E_VICTORY,
		NpcID.TEMPOROSS_INSTANCE_HOST_W_VICTORY,
		NpcID.TEMPOROSS_INSTANCE_HOST_N_VICTORY,
		NpcID.TEMPOROSS_INSTANCE_HOST_S_VICTORY
	};

	// Both island shrines share this ID; north vs south is the tile, not the ID.
	static final int SHRINE = net.runelite.api.ObjectID.SHRINE_41236;
	static final int SHIP_PUMP = net.runelite.api.ObjectID.WATER_PUMP_41000;
	static final int DOCK_PUMP = net.runelite.api.ObjectID.WATER_PUMP_41004;
	static final int SOLO_LADDER = net.runelite.api.ObjectID.ROPE_LADDER_41305;
	static final int BUCKET_CRATE = net.runelite.api.ObjectID.BUCKETS;
	static final int ROPE_CRATE = net.runelite.api.ObjectID.ROPES;
	static final int HAMMER_CRATE = net.runelite.api.ObjectID.HAMMERS_40964;
	static final int HAMMER_CRATE_ALT = net.runelite.api.ObjectID.HAMMERS;
	static final int HARPOON_CRATE = net.runelite.api.ObjectID.HARPOONS;
	static final int DAMAGED_TOTEM = net.runelite.api.ObjectID.DAMAGED_TOTEM_POLE;
	static final int DAMAGED_TOTEM_2 = net.runelite.api.ObjectID.DAMAGED_TOTEM_POLE_41011;
	static final int DAMAGED_MAST = net.runelite.api.ObjectID.DAMAGED_MAST_40996;
	static final int DAMAGED_MAST_2 = net.runelite.api.ObjectID.DAMAGED_MAST_40997;
	static final int TOTEM_A = net.runelite.api.NullObjectID.NULL_41354;
	static final int TOTEM_B = net.runelite.api.NullObjectID.NULL_41355;
	static final int MAST_A = net.runelite.api.NullObjectID.NULL_41352;
	static final int MAST_B = net.runelite.api.NullObjectID.NULL_41353;
	static final int CLOUD = net.runelite.api.NullObjectID.NULL_41006;

	static final int[] HARPOONS = {
		ItemID.HARPOON,
		ItemID.HUNTING_BARBED_HARPOON,
		ItemID.DRAGON_HARPOON,
		ItemID.INFERNAL_HARPOON,
		ItemID.INFERNAL_HARPOON_EMPTY,
		ItemID.CRYSTAL_HARPOON,
		ItemID.CRYSTAL_HARPOON_INACTIVE,
		ItemID.TRAILBLAZER_HARPOON,
		ItemID.TRAILBLAZER_HARPOON_EMPTY,
		ItemID.TRAILBLAZER_HARPOON_NO_INFERNAL,
		ItemID.TRAILBLAZER_RELOADED_HARPOON,
		ItemID.TRAILBLAZER_RELOADED_HARPOON_EMPTY,
		ItemID.TRAILBLAZER_RELOADED_HARPOON_NO_INFERNAL
	};

	private static final Set<Integer> HARPOON_SET = toSet(HARPOONS);
	private static final Set<Integer> SPOT_SET = toSet(FISHING_SPOTS);
	private static final Set<Integer> AMMO_SET = toSet(AMMO_CRATES);
	private static final Set<Integer> FIRE_SET = toSet(FIRES);
	private static final Set<Integer> HOST_SET = toSet(HOSTS);
	private static final Set<Integer> VICTORY_SET = toSet(VICTORY_HOSTS);

	private TemporossIds()
	{
	}

	static boolean isHarpoon(int id)
	{
		return HARPOON_SET.contains(id);
	}

	static boolean isFishingSpot(int id)
	{
		return SPOT_SET.contains(id);
	}

	static boolean isHarpoonSpot(NPC npc)
	{
		if (npc == null)
		{
			return false;
		}
		int id = npc.getId();
		if (isSpiritPool(id) || !isFishingSpot(id))
		{
			return false;
		}
		return hasAction(npc, "Harpoon");
	}

	static boolean isSouthFishingSpot(int id)
	{
		return id == NpcID.TEMPOROSS_HARPOONFISH_FISHINGSPOT_SOUTH;
	}

	static boolean isDoubleSpot(int id)
	{
		return id == DOUBLE_SPOT;
	}

	static boolean isAmmoCrate(int id)
	{
		return AMMO_SET.contains(id);
	}

	static boolean isAmmoCrateNpc(NPC npc)
	{
		if (npc == null)
		{
			return false;
		}
		if (isAmmoCrate(npc.getId()) || hasAction(npc, "Check-ammo"))
		{
			return true;
		}
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null || comp.getName() == null)
		{
			return false;
		}
		return comp.getName().toLowerCase().contains("ammunition");
	}

	static boolean isFireNpc(int id)
	{
		return FIRE_SET.contains(id);
	}

	static boolean isFireTargetNpc(int id)
	{
		return id == NpcID.TEMPOROSS_FIRE_TARGET_NPC;
	}

	static boolean isActiveFireNpc(int id)
	{
		return id == NpcID.TEMPOROSS_FIRE_HITBOX;
	}

	static boolean isHost(int id)
	{
		return HOST_SET.contains(id);
	}

	static boolean isVictoryHost(int id)
	{
		return VICTORY_SET.contains(id);
	}

	static boolean isWestHost(int id)
	{
		return id == NpcID.TEMPOROSS_INSTANCE_HOST_W
			|| id == NpcID.TEMPOROSS_INSTANCE_HOST_W_VICTORY
			|| id == NpcID.TEMPOROSS_INSTANCE_HOST_N
			|| id == NpcID.TEMPOROSS_INSTANCE_HOST_N_VICTORY;
	}

	static boolean isSpiritPool(int id)
	{
		return id == SPIRIT_POOL;
	}

	static boolean isSpiritPoolAttackable(NPC npc)
	{
		return npc != null && isSpiritPool(npc.getId()) && hasAction(npc, "Harpoon");
	}

	static boolean isShrine(int id)
	{
		return id == SHRINE;
	}

	static boolean isPump(int id)
	{
		return id == SHIP_PUMP || id == DOCK_PUMP;
	}

	static boolean isSoloLadder(int id)
	{
		return id == SOLO_LADDER;
	}

	static boolean isBucketCrate(int id)
	{
		return id == BUCKET_CRATE;
	}

	static boolean isRopeCrate(int id)
	{
		return id == ROPE_CRATE;
	}

	static boolean isHammerCrate(int id)
	{
		return id == HAMMER_CRATE || id == HAMMER_CRATE_ALT;
	}

	static boolean isHarpoonCrate(int id)
	{
		return id == HARPOON_CRATE;
	}

	static boolean isDamagedTotem(int id)
	{
		return id == DAMAGED_TOTEM || id == DAMAGED_TOTEM_2;
	}

	static boolean isDamagedMast(int id)
	{
		return id == DAMAGED_MAST || id == DAMAGED_MAST_2;
	}

	static boolean isTotem(int id)
	{
		return id == TOTEM_A || id == TOTEM_B || isDamagedTotem(id);
	}

	static boolean isMast(int id)
	{
		return id == MAST_A || id == MAST_B || isDamagedMast(id);
	}

	static boolean isCloud(int id)
	{
		return id == CLOUD;
	}

	static boolean isTrackedObject(TileObject object)
	{
		if (object == null)
		{
			return false;
		}
		int id = object.getId();
		return isShrine(id) || isPump(id) || isSoloLadder(id) || isBucketCrate(id)
			|| isRopeCrate(id) || isHammerCrate(id) || isHarpoonCrate(id)
			|| isTotem(id) || isMast(id) || isCloud(id);
	}

	static boolean isTrackedNpc(NPC npc)
	{
		if (npc == null)
		{
			return false;
		}
		int id = npc.getId();
		if (isFishingSpot(id) || isAmmoCrateNpc(npc) || isFireNpc(id) || isHost(id)
			|| isSpiritPool(id))
		{
			return true;
		}
		return hasAction(npc, "Douse") || hasAction(npc, "Check-ammo") || hasAction(npc, "Leave")
			|| hasAction(npc, "Forfeit") || hasAction(npc, "Harpoon");
	}

	static boolean hasAction(NPC npc, String action)
	{
		if (npc == null || action == null)
		{
			return false;
		}
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null || comp.getActions() == null)
		{
			return false;
		}
		for (String a : comp.getActions())
		{
			if (action.equals(a))
			{
				return true;
			}
		}
		return false;
	}

	private static Set<Integer> toSet(int[] ids)
	{
		Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return set;
	}
}

package com.easytempoross;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

@Singleton
public class WaveTracker
{
	@Getter
	private boolean incoming;
	@Getter
	private boolean tethered;

	@Inject
	WaveTracker()
	{
	}

	public void reset()
	{
		incoming = false;
		tethered = false;
	}

	public void setTethered(boolean tethered)
	{
		this.tethered = tethered;
	}

	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE || event.getMessage() == null)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		if (message.contains("A colossal wave closes in"))
		{
			incoming = true;
			return;
		}
		if (message.contains("the rope keeps you securely") || message.contains("the wave slams into you"))
		{
			incoming = false;
		}
	}
}

package com.easytempoross;

import net.runelite.api.coords.WorldPoint;

/**
 * West boat, north island. Solos always spawn there.
 */
final class WorkArea
{
	private final WorldPoint host;
	private final WorldPoint shrine;
	private final WorldPoint totem;
	private final WorldPoint mast;
	private final WorldPoint pump;
	private final WorldPoint ammo;
	private final WorldPoint spiritPool;
	private final WorldPoint island;

	private WorkArea(WorldPoint host, WorldPoint shrine, WorldPoint spiritPool)
	{
		this.host = host;
		this.pump = host.dx(-3).dy(-2);
		this.mast = host.dx(0).dy(-3);
		this.ammo = host.dx(0).dy(-1);
		this.totem = host.dx(8).dy(15);
		this.shrine = shrine;
		this.spiritPool = spiritPool;
		this.island = host.dx(4).dy(-12);
	}

	static WorkArea fromSpawn(WorldPoint spawn, WorldPoint host)
	{
		return fromSpawn(spawn, host, RotationConstants.NORTH_SHRINE, RotationConstants.NORTH_SPIRIT);
	}

	/**
	 * The shrine and spirit pool are fixed points, but Tempoross is instanced so they have to be
	 * passed in already translated into the loaded scene.
	 */
	static WorkArea fromSpawn(WorldPoint spawn, WorldPoint host, WorldPoint shrine, WorldPoint spiritPool)
	{
		return new WorkArea(host != null ? host : spawn, shrine, spiritPool);
	}

	static boolean isNorthShore(WorldPoint point)
	{
		return point != null && point.getY() >= RotationConstants.NORTH_SHORE_MIN_Y;
	}

	WorldPoint getHost()
	{
		return host;
	}

	WorldPoint getShrine()
	{
		return shrine;
	}

	WorldPoint getTotem()
	{
		return totem;
	}

	WorldPoint getMast()
	{
		return mast;
	}

	WorldPoint getPump()
	{
		return pump;
	}

	WorldPoint getAmmo()
	{
		return ammo;
	}

	WorldPoint getSpiritPool()
	{
		return spiritPool;
	}

	WorldPoint getIsland()
	{
		return island;
	}

	boolean isOnShip(WorldPoint player)
	{
		return within(player, host, 12) || within(player, mast, 12)
			|| within(player, pump, 10) || within(player, ammo, 8);
	}

	boolean isOnIsland(WorldPoint player)
	{
		return within(player, shrine, 16) || within(player, totem, 12) || within(player, island, 10);
	}

	/**
	 * Generous "our half of the cove" test. Wide enough to catch every fire that belongs to the
	 * west boat and north island, but still far short of the south shrine.
	 */
	boolean isOurSide(WorldPoint point)
	{
		return within(point, shrine, 26) || within(point, totem, 22)
			|| within(point, host, 20) || within(point, mast, 20) || within(point, ammo, 20);
	}

	private static boolean within(WorldPoint player, WorldPoint landmark, int tiles)
	{
		return player != null && landmark != null && player.distanceTo(landmark) <= tiles;
	}
}

package com.easytempoross.overlay;

import com.easytempoross.EasyTemporossConfig;
import com.easytempoross.RotationHelper;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class DepositCountdownOverlay extends Overlay
{
	private static final Color CALM = new Color(120, 210, 235);
	private static final Color ALERT = new Color(255, 180, 60);
	private static final Color STOP = new Color(235, 80, 70);
	private static final Color CAPTION = new Color(190, 190, 190);
	private static final Color BACKDROP = new Color(0, 0, 0, 140);
	private static final int ALERT_AT = 3;
	private static final int PAD = 10;
	private static final int GAP = 2;

	private final EasyTemporossConfig config;
	private final RotationHelper rotationHelper;

	@Inject
	private DepositCountdownOverlay(EasyTemporossConfig config, RotationHelper rotationHelper)
	{
		setPosition(OverlayPosition.TOP_CENTER);
		setPriority(Overlay.PRIORITY_HIGH);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		this.config = config;
		this.rotationHelper = rotationHelper;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableHelper() || !config.showDepositCountdown())
		{
			return null;
		}

		int left = rotationHelper.getDepositActionsLeft();
		if (left <= 0)
		{
			return null;
		}

		boolean alert = left <= ALERT_AT;
		Object hint = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		float size = config.depositCountdownSize() * (alert ? 1f : 0.6f);
		Font numberFont = FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, size);
		String count = String.valueOf(left);
		String caption = left == 1 ? "last deposit" : "deposits left";

		graphics.setFont(numberFont);
		FontMetrics numbers = graphics.getFontMetrics();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics captions = graphics.getFontMetrics();

		int numberWidth = numbers.stringWidth(count);
		int captionWidth = captions.stringWidth(caption);
		int width = Math.max(numberWidth, captionWidth) + PAD * 2;
		int height = numbers.getAscent() + GAP + captions.getHeight() + PAD * 2;

		graphics.setColor(BACKDROP);
		graphics.fillRoundRect(0, 0, width, height, 8, 8);

		int numberY = PAD + numbers.getAscent();
		graphics.setFont(numberFont);
		draw(graphics, count, (width - numberWidth) / 2, numberY, color(left));

		graphics.setFont(FontManager.getRunescapeSmallFont());
		draw(graphics, caption, (width - captionWidth) / 2, numberY + GAP + captions.getAscent(), CAPTION);

		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
			hint != null ? hint : RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		return new Dimension(width, height);
	}

	private static Color color(int left)
	{
		if (left == 1)
		{
			return STOP;
		}
		return left <= ALERT_AT ? ALERT : CALM;
	}

	private static void draw(Graphics2D graphics, String text, int x, int y, Color color)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}
}

