public class PathMinimapOverlay extends Overlay
{
	private static final int MINIMAP_RANGE = 6400;
	private static final Stroke PATH_OUTLINE = new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Stroke PATH_LINE = new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	private final Client client;
	private final EasyTemporossConfig config;
	private final RotationHelper rotationHelper;

	@Inject
	private PathMinimapOverlay(Client client, EasyTemporossConfig config, RotationHelper rotationHelper)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_LOW);
		this.client = client;
		this.config = config;
		this.rotationHelper = rotationHelper;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableHelper() || !config.pathDisplay().showsMinimap())
		{
			return null;
		}

		HelperAction action = rotationHelper.getCurrentAction();
		if (action == null || action.getStep() == RotationStep.IDLE
			|| action.getPath() == null || action.getPath().size() < 2)
		{
			return null;
		}

		Color base = action.getColor() != null ? action.getColor() : Color.CYAN;
		renderPath(graphics, action.getPath(), base);
		return null;
	}

	private void renderPath(Graphics2D graphics, List<WorldPoint> path, Color base)
	{
		Player player = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		Path2D.Float line = new Path2D.Float();
		boolean started = false;
		boolean pendingGap = false;
		WorldPoint here = player == null ? null : player.getWorldLocation();
		if (player != null)
		{
			Point mini = toMinimap(player.getWorldLocation(), worldView, player);
			if (mini != null)
			{
				line.moveTo(mini.getX(), mini.getY());
				started = true;
			}
		}

		for (int i = 0; i < path.size(); i++)
		{
			WorldPoint tile = path.get(i);
			if (i == 0 && here != null && tile.distanceTo(here) <= 1 && path.size() > 1)
			{
				continue;
			}
			Point mini = toMinimap(tile, worldView, player);
			if (mini == null)
			{
				pendingGap = true;
				continue;
			}
			if (!started)
			{
				line.moveTo(mini.getX(), mini.getY());
				started = true;
			}
			else if (pendingGap)
			{
				line.moveTo(mini.getX(), mini.getY());
			}
			else
			{
				line.lineTo(mini.getX(), mini.getY());
			}
			pendingGap = false;
		}

		if (!started)
		{
			return;
		}

		Stroke oldStroke = graphics.getStroke();
		Object oldHint = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setStroke(PATH_OUTLINE);
		graphics.setColor(new Color(0, 0, 0, 140));
		graphics.draw(line);
		graphics.setStroke(PATH_LINE);
		graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 220));
		graphics.draw(line);
		graphics.setStroke(oldStroke);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			oldHint != null ? oldHint : RenderingHints.VALUE_ANTIALIAS_OFF);
	}

	private Point toMinimap(WorldPoint tile, WorldView worldView, Player player)
	{
		if (tile == null)
		{
			return null;
		}
		LocalPoint local = LocalPoint.fromWorld(worldView, tile);
		if (local == null && player != null && player.getWorldLocation() != null)
		{
			LocalPoint here = player.getLocalLocation();
			WorldPoint playerWorld = player.getWorldLocation();
			if (here != null && playerWorld.getPlane() == tile.getPlane())
			{
				int x = here.getX() + (tile.getX() - playerWorld.getX()) * Perspective.LOCAL_TILE_SIZE;
				int y = here.getY() + (tile.getY() - playerWorld.getY()) * Perspective.LOCAL_TILE_SIZE;
				local = new LocalPoint(x, y, worldView);
			}
		}
		if (local == null)
		{
			return null;
		}
		return Perspective.localToMinimap(client, local, MINIMAP_RANGE);
	}
}

package com.easytempoross.overlay;

import com.easytempoross.EasyTemporossConfig;
import com.easytempoross.EasyTemporossPlugin;
import com.easytempoross.GameSnapshot;
import com.easytempoross.HelperAction;
import com.easytempoross.IdleReminder;
import com.easytempoross.InventorySnapshot;
import com.easytempoross.RotationHelper;
import com.easytempoross.RotationStep;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;

import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

public class StatusOverlay extends OverlayPanel
{
	private static final Color LABEL = Color.WHITE;
	private static final Color DETAIL = new Color(170, 170, 170);
	private static final Color WARN = new Color(255, 168, 76);
	private static final Color STORM_FLASH = new Color(255, 60, 50);
	private static final Color ENERGY = new Color(0, 200, 220);
	private static final Color ESSENCE = new Color(82, 161, 82);
	private static final Color STORM = new Color(220, 220, 220);
	private static final Color BAR_BACK = new Color(40, 40, 40, 180);
	private static final Dimension BAR_SIZE = new Dimension(150, 14);
	private static final Dimension SIZE = new Dimension(166, 0);
	private static final long STORM_FLASH_MS = 400L;

	private final EasyTemporossConfig config;
	private final RotationHelper rotationHelper;
	private final IdleReminder idleReminder;

	@Inject
	private StatusOverlay(
		EasyTemporossPlugin plugin,
		EasyTemporossConfig config,
		RotationHelper rotationHelper,
		IdleReminder idleReminder)
	{
		super(plugin);
		setPosition(OverlayPosition.TOP_LEFT);
		this.config = config;
		this.rotationHelper = rotationHelper;
		this.idleReminder = idleReminder;
		panelComponent.setBorder(new Rectangle(6, 6, 6, 6));
		panelComponent.setGap(new Point(0, 3));
		panelComponent.setPreferredSize(SIZE);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Jam's Solo Tempoross");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		HelperAction action = rotationHelper.getCurrentAction();
		GameSnapshot game = rotationHelper.getGameSnapshot();
		boolean showHud = config.replaceGameHud()
			&& game != null
			&& game.isInMinigame()
			&& !game.isAtUnkah()
			&& game.isHudVisible();
		boolean showRotation = config.showStatusPanel()
			&& config.enableHelper()
			&& game != null
			&& (game.isInMinigame() || game.isAtUnkah())
			&& action != null
			&& action.getStep() != RotationStep.IDLE;
		List<String> warnings = config.showStatusPanel() ? idleReminder.getWarnings() : List.of();

		if (!showHud && !showRotation && warnings.isEmpty())
		{
			return null;
		}

		if (showHud)
		{
			renderCompactHud(game);
		}

		if (showRotation)
		{
			if (showHud)
			{
				panelComponent.getChildren().add(spacer());
			}
			Color stepColor = action.getColor() != null ? action.getColor() : Color.WHITE;
			String next = action.isRecover() ? "Recover" : "Next";
			panelComponent.getChildren().add(line(next, action.getStep().getLabel(), stepColor));
			if (action.getDetail() != null && !action.getDetail().isEmpty())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(action.getDetail())
					.leftColor(action.isRecover() ? WARN : DETAIL)
					.leftFont(FontManager.getRunescapeSmallFont())
					.build());
			}

			InventorySnapshot inv = rotationHelper.getSnapshot();
			if (inv != null)
			{
				panelComponent.getChildren().add(line("Raw", String.valueOf(inv.getRawFish()), LABEL));
				panelComponent.getChildren().add(line("Cooked", String.valueOf(inv.getDumpableFish()), LABEL));
				panelComponent.getChildren().add(line("Buckets", String.valueOf(inv.getWaterBuckets())
					+ "/" + inv.getBuckets(), LABEL));
			}
		}

		for (String warning : warnings)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(warning)
				.leftColor(WARN)
				.build());
		}

		return super.render(graphics);
	}

	private void renderCompactHud(GameSnapshot game)
	{
		addBar("Energy", game.getEnergy(), ENERGY);
		addBar("Essence", game.getEssence(), ESSENCE);
		Color stormFill = stormBarColor(game.getIntensity(), rotationHelper.isStormHurry());
		addBar("Storm", game.getIntensity(), stormFill);
		if (game.getPoints() >= 0)
		{
			panelComponent.getChildren().add(line("Points", String.valueOf(game.getPoints()), LABEL));
		}
	}

	private void addBar(String label, int value, Color fill)
	{
		if (value < 0)
		{
			return;
		}
		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMaximum(100);
		bar.setValue(value);
		bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
		bar.setCenterLabel(label + ": " + value + "%");
		bar.setForegroundColor(fill);
		bar.setBackgroundColor(BAR_BACK);
		bar.setFontColor(LABEL);
		bar.setPreferredSize(BAR_SIZE);
		panelComponent.getChildren().add(bar);
	}

	private static Color stormBarColor(int intensity, boolean hurry)
	{
		if (!hurry || intensity < 90)
		{
			return intensity >= 90 ? WARN : STORM;
		}
		boolean flash = (System.currentTimeMillis() / STORM_FLASH_MS) % 2 == 0;
		return flash ? STORM_FLASH : WARN;
	}

	private static LineComponent spacer()
	{
		return LineComponent.builder().left("").build();
	}

	private static LineComponent line(String left, String right, Color rightColor)
	{
		return LineComponent.builder()
			.left(left)
			.leftColor(LABEL)
			.right(right)
			.rightColor(rightColor)
			.build();
	}
}

package com.easytempoross.overlay;

import com.easytempoross.EasyTemporossConfig;
import com.easytempoross.RotationHelper;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Phase-1 alarm when storm intensity hits 90% before the first dump is finished.
 */
public class StormHurryOverlay extends Overlay
{
	private static final Color TITLE = new Color(255, 70, 60);
	private static final Color TITLE_FLASH = new Color(255, 200, 40);
	private static final Color CAPTION = new Color(230, 210, 200);
	private static final Color BACKDROP = new Color(0, 0, 0, 160);
	private static final int PAD = 12;
	private static final int GAP = 4;
	private static final long FLASH_MS = 400L;

	private final EasyTemporossConfig config;
	private final RotationHelper rotationHelper;

	@Inject
	private StormHurryOverlay(EasyTemporossConfig config, RotationHelper rotationHelper)
	{
		setPosition(OverlayPosition.TOP_CENTER);
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		this.config = config;
		this.rotationHelper = rotationHelper;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableHelper() || !rotationHelper.isStormHurry())
		{
			return null;
		}

		Object hint = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		float size = Math.max(36f, config.depositCountdownSize() * 0.9f);
		Font titleFont = FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, size);
		String title = "HURRY";
		String caption = "dump before the storm";

		graphics.setFont(titleFont);
		FontMetrics titles = graphics.getFontMetrics();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics captions = graphics.getFontMetrics();

		int titleWidth = titles.stringWidth(title);
		int captionWidth = captions.stringWidth(caption);
		int width = Math.max(titleWidth, captionWidth) + PAD * 2;
		int height = titles.getAscent() + GAP + captions.getHeight() + PAD * 2;

		graphics.setColor(BACKDROP);
		graphics.fillRoundRect(0, 0, width, height, 8, 8);

		boolean flash = (System.currentTimeMillis() / FLASH_MS) % 2 == 0;
		int titleY = PAD + titles.getAscent();
		graphics.setFont(titleFont);
		draw(graphics, title, (width - titleWidth) / 2, titleY, flash ? TITLE_FLASH : TITLE);

		graphics.setFont(FontManager.getRunescapeSmallFont());
		draw(graphics, caption, (width - captionWidth) / 2, titleY + GAP + captions.getAscent(), CAPTION);

		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
			hint != null ? hint : RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		return new Dimension(width, height);
	}

	private static void draw(Graphics2D graphics, String text, int x, int y, Color color)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}
}

package com.easytempoross;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ChimePolicyTest
{
	@Test
	public void depositOnlyNeverPlaysActionStop()
	{
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.FISH, RotationStep.COOK, ChimeMode.DEPOSIT_ONLY));
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.COOK, RotationStep.DEPOSIT, ChimeMode.DEPOSIT_ONLY));
	}

	@Test
	public void allActionsPlaysWhenFishingOrCookingFinishes()
	{
		assertTrue(ChimePolicy.shouldPlayActionStop(
			RotationStep.FISH, RotationStep.COOK, ChimeMode.ALL_ACTIONS));
		assertTrue(ChimePolicy.shouldPlayActionStop(
			RotationStep.COOK, RotationStep.DEPOSIT, ChimeMode.ALL_ACTIONS));
		assertTrue(ChimePolicy.shouldPlayActionStop(
			RotationStep.SPIRIT, RotationStep.FISH, ChimeMode.ALL_ACTIONS));
		assertTrue(ChimePolicy.shouldPlayActionStop(
			RotationStep.FILL_PUMP, RotationStep.LEAVE_SHIP, ChimeMode.ALL_ACTIONS));
	}

	@Test
	public void allActionsSkipsDepositBecauseCountdownAlreadyStops()
	{
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.DEPOSIT, RotationStep.SPIRIT, ChimeMode.ALL_ACTIONS));
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.DEPOSIT_KEEP3, RotationStep.DOUSE, ChimeMode.ALL_ACTIONS));
	}

	@Test
	public void allActionsSkipsSameActivityAndNonAfk()
	{
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.FISH, RotationStep.FISH_DOUBLE, ChimeMode.ALL_ACTIONS));
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.FISH, RotationStep.FISH, ChimeMode.ALL_ACTIONS));
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.PREP, RotationStep.SOLO_START, ChimeMode.ALL_ACTIONS));
		assertFalse(ChimePolicy.shouldPlayActionStop(
			RotationStep.IDLE, RotationStep.FISH, ChimeMode.ALL_ACTIONS));
		assertTrue(ChimePolicy.shouldPlayActionStop(
			RotationStep.FISH, RotationStep.TETHER, ChimeMode.ALL_ACTIONS));
	}

	@Test
	public void doubleFishPlaysOnEdgeWhenInventoryHasSpace()
	{
		assertTrue(ChimePolicy.shouldPlayDoubleFish(
			true, true, RotationStep.FISH_DOUBLE, 3, false));
		assertFalse(ChimePolicy.shouldPlayDoubleFish(
			true, true, RotationStep.FISH_DOUBLE, 3, true));
	}

	@Test
	public void doubleFishSkipsWhenFullOrNotDoubleOrDisabled()
	{
		assertFalse(ChimePolicy.shouldPlayDoubleFish(
			true, true, RotationStep.FISH_DOUBLE, 0, false));
		assertFalse(ChimePolicy.shouldPlayDoubleFish(
			true, true, RotationStep.FISH, 3, false));
		assertFalse(ChimePolicy.shouldPlayDoubleFish(
			false, true, RotationStep.FISH_DOUBLE, 3, false));
		assertFalse(ChimePolicy.shouldPlayDoubleFish(
			true, false, RotationStep.FISH_DOUBLE, 3, false));
	}
}

